arguments.argument:
if moni_go_waits!=0
{
    moni_go_waits=4
    if (global.player_control=player or (!fn_get_my_player_id(global.socket) and global.player_com[player])) and instance_number(moni_go_waits_id)
    {
        moni_go_waits_id.moni-=attack_power
        /*on*/buffer_clear(fnv_sned)
        write_uint(fnv_sned, moni_go_waits_id.on)
        write_uint(fnv_sned, attack_power)
        fn_message_send(global.socket, send_other, 13)
        /*on*/buffer_clear(fnv_sned)
        write_uint(fnv_sned, on)
        if 100>unit_id{write_uint(fnv_sned, ds_list_find_value(global.moni_hp_minus, 0))}
        else{write_uint(fnv_sned, ds_list_find_value(global.moni_hp_minus, 1))}
        fn_message_send(global.socket, send_all_server_me, 26)
    }
}
